import java.util.ArrayList;
import java.util.List;

interface Observador {
    void actualizar(String mensaje);
}

class Suscriptor implements Observador {
    private String nombre;
    public Suscriptor(String nombre) { this.nombre = nombre; }

    public void actualizar(String mensaje) {
        System.out.println(nombre + " recibió: " + mensaje);
    }
}

class Canal {
    private List<Observador> suscriptores = new ArrayList<>();

    public void suscribir(Observador o) {
        suscriptores.add(o);
    }

    private void notificar(String mensaje) {
        for (Observador o : suscriptores) {
            o.actualizar(mensaje);
        }
    }

    public void subirVideo(String titulo) {
        System.out.println("Canal subió: " + titulo);
        notificar("Nuevo video: " + titulo);
    }
}

public class Main {
    public static void main(String[] args) {
        Canal miCanal = new Canal();
        miCanal.suscribir(new Suscriptor("Alice"));
        miCanal.subirVideo("Patrón Observer en Java");
    }
}
